(async () => {
 const body=document.getElementById('body'),root=document.getElementById('root'),rich=WebWindowsNewsContent,editor=WebWindowsAdminRichText.create(root,body); let count=0;
 const check=(value,name)=>{if(!value)throw Error(name);count++;};
 const select=(node=body)=>{body.focus();const range=document.createRange();range.selectNodeContents(node);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);body.dispatchEvent(new Event('mouseup'));};
 const click=name=>root.querySelector(`button[data-command="${name}"]`).click();
 const change=(name,value)=>{const control=root.querySelector(`[data-command="${name}"]`);control.value=value;control.dispatchEvent(new Event('change',{bubbles:true}));};
 try {
  editor.setContent('<p>中文正文</p>');editor.setEnabled(true);select();click('bold');check(/<(b|strong)>/.test(editor.getContent()),'bold');click('undo');check(!/<(b|strong)>/.test(editor.getContent()),'undo');click('redo');check(/<(b|strong)>/.test(editor.getContent()),'redo');
  for(const [command,value] of [['italic',''],['underline',''],['strikeThrough',''],['fontName','Georgia'],['fontSize','5'],['foreColor','#123456'],['hiliteColor','#abcdef'],['justifyCenter',''],['formatBlock','h3']]) {select();if(value)change(command,value);else click(command);}
  const format=editor.getContent();check(/<h3/.test(format),'heading');check(/font-family:Georgia/i.test(format),'font');check(/font-size:24px/.test(format),'size');check(/color:(#123456|rgb\(18, 52, 86\))/.test(format),'color');check(/background-color:/.test(format),'background');check(/text-align:center/.test(format),'alignment');check(/<(i|em)>/.test(format),'italic');check(/<u>/.test(format),'underline');check(/<(strike|s|del)>|line-through/.test(format),'strike');
  editor.setContent('<p>条目</p>');select();click('insertUnorderedList');check(!!body.querySelector('ul li'),'list');
  editor.setContent('<p>图片表格</p>');select();click('table');let dialog=root.querySelector('dialog');dialog.querySelector('form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));check(body.querySelectorAll('td').length===4,'insert table');
  select(body.querySelector('td'));change('tableAction','rowAfter');check(body.querySelectorAll('tr').length===3,'row insert');select(body.querySelector('td'));change('tableAction','colAfter');check(body.querySelectorAll('td').length===9,'col insert');select(body.querySelector('td'));change('tableAction','rowDelete');check(body.querySelectorAll('tr').length===2,'row remove');select(body.querySelector('td'));change('tableAction','colDelete');check(body.querySelectorAll('td').length===4,'col remove');
  select(body.querySelector('td'));click('link');dialog=root.querySelector('dialog');dialog.querySelector('input').value='https://example.com/';dialog.querySelector('form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));check(!!body.querySelector('a[href="https://example.com/"]'),'link');
  select(body.querySelector('a'));click('unlink');check(!body.querySelector('a'),'unlink');
  editor.setContent('<p>图片和链接</p>');select();click('image');dialog=root.querySelector('dialog');dialog.querySelector('input').value='data:image/png,x';dialog.querySelector('form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));check(dialog.open && !body.querySelector('img'),'reject data image dialog');dialog.querySelector('input').value='https://example.com/image.png';dialog.querySelector('form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));check(!!body.querySelector('img[src="https://example.com/image.png"]'),'insert https image');click('undo');check(!body.querySelector('img'),'image undo');click('redo');check(!!body.querySelector('img'),'image redo');
  editor.setContent('<p>缩进正文</p>');select();click('indent');check(/margin-left:40px/.test(editor.getContent()),'indent survives clean');select();click('outdent');check(!/margin-left:40px/.test(editor.getContent()),'outdent');select();change('formatBlock','pre');check(!!body.querySelector('pre'),'code block');select();change('formatBlock','blockquote');check(!!body.querySelector('blockquote'),'quote block');click('insertHorizontalRule');check(!!body.querySelector('hr'),'horizontal rule');
  editor.setContent('<p>键盘快捷键</p>');select();body.dispatchEvent(new KeyboardEvent('keydown',{key:'b',ctrlKey:true,bubbles:true}));check(/<(b|strong)>/.test(editor.getContent()),'keyboard bold');body.dispatchEvent(new KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true}));check(!/<(b|strong)>/.test(editor.getContent()),'keyboard undo');
  const original=editor.getContent();click('source');check(!root.querySelector('textarea').hidden,'source visible');root.querySelector('textarea').value=original+'<script>evil()</script><p style="position:fixed;color:#123456" onclick="evil()">源码正文</p><img src="data:x"><a href="javascript:x">bad</a>';
  check(!/script|onclick|position:|data:x|javascript:x/.test(editor.getContent()),'source save safe');click('source');check(body.textContent.includes('源码正文'),'source visual');check(!body.querySelector('script,[onclick]'),'source cleaned');click('undo');check(editor.getContent()===original,'source undo');
  click('fullscreen');check(root.classList.contains('ww-rich-fullscreen'),'fullscreen');root.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));check(!root.classList.contains('ww-rich-fullscreen'),'escape');
  editor.setContent('<p>粘贴</p>');select();const paste=new Event('paste',{bubbles:true,cancelable:true});Object.defineProperty(paste,'clipboardData',{value:{getData:format=>format==='text/html'?'<h2>复制标题</h2><span style="color:#ff0000" onmouseover="evil()">复制正文</span><script>evil()</script>':''}});body.dispatchEvent(paste);check(!!body.querySelector('h2'),'paste heading');check(!body.querySelector('script,[onmouseover]'),'paste clean');
  const holder=document.createElement('div');rich.load(holder,'一行\n二行');check(holder.textContent==='一行\n二行','plain line breaks');rich.load(holder,'<table><tr><td colspan="2">表</td></tr></table><img src="https://example.com/a.png" alt="图"><a href="javascript:x">链接</a><svg><script>x</script></svg>');check(!!holder.querySelector('table td[colspan="2"]'),'sanitize table');check(!!holder.querySelector('img'),'https image');check(!holder.querySelector('svg,script,a[href]'),'URL rejection');check(!rich.safeLink('data:image/png,x',true),'data rejected');check(!rich.safeStyle('color:rgb(999,0,0);background:url(x)'),'CSS rejected');
  const saved=editor.getContent();editor.setContent('');editor.setContent(saved);check(editor.getContent()===saved,'reopen preserves body');editor.setEnabled(false);check(root.querySelector('[data-command="bold"]').disabled,'disabled while loading');editor.setEnabled(true);
  editor.setContent('<h2>完整正文已加载</h2><p>可使用工具栏设置字体、颜色、列表和对齐。</p><blockquote>保存后再次编辑，正文与格式均应保留。</blockquote><table><tbody><tr><th>项目</th><th>结果</th></tr><tr><td>详情读取</td><td>完整加载</td></tr><tr><td>格式保存</td><td>可再次编辑</td></tr></tbody></table>');
  document.getElementById('result').textContent=`PASS ${count}：浏览器原生排版、撤销、表格、链接、源码、粘贴清洗、再次加载全部通过`;
 } catch(error){document.getElementById('result').textContent='FAIL '+error.stack;}
})();
